import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { dirname, resolve, sep } from 'node:path'
import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'
import { env } from '../../config/env.js'

/** Private file storage. Keys are generated by the app; uploaded names are never used as paths. */
export interface FileStorage {
  readonly kind: 'local' | 's3'
  put(key: string, body: Buffer, contentType: string): Promise<void>
  get(key: string): Promise<Buffer>
  remove(key: string): Promise<void>
  /** Short-lived download URL after authorization (S3), or null to stream through the API (local). */
  signedUrl(key: string, filename: string, contentType: string): Promise<string | null>
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/._-]{0,200}$/

/** Development/single-server storage on disk, outside any public web root. */
export function localStorage(rootDir: string): FileStorage {
  const root = resolve(rootDir)
  const pathOf = (key: string) => {
    if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('invalid storage key')
    const p = resolve(root, key)
    if (!p.startsWith(root + sep)) throw new Error('invalid storage key') // no path traversal
    return p
  }
  return {
    kind: 'local',
    async put(key, body) {
      const p = pathOf(key)
      await mkdir(dirname(p), { recursive: true })
      await writeFile(p, body, { flag: 'wx' }) // never overwrite an existing file
    },
    get: async (key) => readFile(pathOf(key)),
    remove: async (key) => rm(pathOf(key), { force: true }),
    signedUrl: async () => null,
  }
}

/** Any S3-compatible bucket (AWS S3, Cloudflare R2, MinIO). Keep the bucket private. Not yet verified against a live bucket. */
export function s3Storage(cfg: { bucket: string; region: string; endpoint?: string | undefined; accessKeyId: string; secretAccessKey: string }): FileStorage {
  const client = new S3Client({ region: cfg.region, ...(cfg.endpoint ? { endpoint: cfg.endpoint, forcePathStyle: true } : {}), credentials: { accessKeyId: cfg.accessKeyId, secretAccessKey: cfg.secretAccessKey } })
  const check = (key: string) => {
    if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('invalid storage key')
    return key
  }
  return {
    kind: 's3',
    async put(key, body, contentType) {
      await client.send(new PutObjectCommand({ Bucket: cfg.bucket, Key: check(key), Body: body, ContentType: contentType, IfNoneMatch: '*' }))
    },
    async get(key) {
      const r = await client.send(new GetObjectCommand({ Bucket: cfg.bucket, Key: check(key) }))
      return Buffer.from(await r.Body!.transformToByteArray())
    },
    async remove(key) {
      await client.send(new DeleteObjectCommand({ Bucket: cfg.bucket, Key: check(key) }))
    },
    signedUrl: (key, filename, contentType) =>
      getSignedUrl(client, new GetObjectCommand({ Bucket: cfg.bucket, Key: check(key), ResponseContentDisposition: `attachment; filename="${filename}"`, ResponseContentType: contentType }), { expiresIn: 300 }),
  }
}

let cached: FileStorage | undefined
export function storage(): FileStorage {
  if (cached) return cached
  cached = env.STORAGE_DRIVER === 's3'
    ? s3Storage({ bucket: env.S3_BUCKET!, region: env.S3_REGION, endpoint: env.S3_ENDPOINT, accessKeyId: env.S3_ACCESS_KEY_ID!, secretAccessKey: env.S3_SECRET_ACCESS_KEY! })
    : localStorage(env.STORAGE_DIR)
  return cached
}
